// Mock the checkout store.
jest.mock('@store/checkouts/store', () => ({
  __esModule: true,
  default: {
    state: { live: {}, test: {} },
    set: jest.fn(),
    get: jest.fn(),
    onChange: jest.fn(),
    on: jest.fn(),
    dispose: jest.fn(),
  },
  state: { live: {}, test: {} },
  set: jest.fn(),
  get: jest.fn(),
  onChange: jest.fn(),
  on: jest.fn(),
  dispose: jest.fn(),
}));

// Mock the checkout module
jest.mock('@store/checkout', () => ({
  state: { checkout: null, formId: null },
  onChange: jest.fn(() => jest.fn()), // Return a cleanup function
}));

// Mock the getters
jest.mock('@store/checkout/getters', () => ({
  fullShippingAddressRequired: jest.fn(() => false),
  shippingAddressRequired: jest.fn(() => false),
  phoneRequired: jest.fn(() => false),
}));

// Mock the processor getters
jest.mock('@store/processors/getters', () => ({
  getAvailableProcessor: jest.fn(() => undefined),
}));

import { h } from '@stencil/core';
import { newSpecPage } from '@stencil/core/testing';
import { Checkout, Processor, TaxProtocol } from '../../../../types';
import { state as checkoutState } from '@store/checkout';
import { ScFormComponentsValidator } from '../sc-form-components-validator';
import { ScCustomerName } from '../../../controllers/checkout-form/customer-name/sc-customer-name';
import { ScOrderShippingAddress } from '../../../controllers/checkout-form/order-shipping-address/sc-order-shipping-address';
import { ScCustomerPhone } from '../../../controllers/checkout-form/customer-phone/sc-customer-phone';
import { fullShippingAddressRequired, shippingAddressRequired, phoneRequired } from '@store/checkout/getters';
import { getAvailableProcessor } from '@store/processors/getters';

// Mock the getter functions
const mockShippingAddressRequired = shippingAddressRequired as jest.MockedFunction<typeof shippingAddressRequired>;
const mockFullShippingAddressRequired = fullShippingAddressRequired as jest.MockedFunction<typeof fullShippingAddressRequired>;
const mockPhoneRequired = phoneRequired as jest.MockedFunction<typeof phoneRequired>;
const mockGetAvailableProcessor = getAvailableProcessor as jest.MockedFunction<typeof getAvailableProcessor>;

describe('sc-form-components-validator', () => {
  beforeEach(() => {
    checkoutState.checkout = null;
    checkoutState.formId = null;
    mockShippingAddressRequired.mockReturnValue(false);
    mockFullShippingAddressRequired.mockReturnValue(false);
    mockPhoneRequired.mockReturnValue(false);
    mockGetAvailableProcessor.mockReturnValue(undefined);
    delete (window as any).wp;
    jest.clearAllMocks();
  });

  it('renders', async () => {
    const page = await newSpecPage({
      components: [ScFormComponentsValidator],
      html: `<sc-form-components-validator></sc-form-components-validator>`,
    });
    expect(page.root).toMatchSnapshot();
    page.rootInstance.disconnectedCallback();
  });

  it('appends missing address field if required', async () => {
    mockShippingAddressRequired.mockReturnValue(true);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });

    // Wait for components to initialize
    await page.waitForChanges();

    checkoutState.checkout = { tax_status: 'address_invalid' } as Checkout;
    await page.waitForChanges();

    expect(page.root).toMatchSnapshot();
    page.rootInstance.disconnectedCallback();
  });

  it('appends missing tax id input if required', async () => {
    const page = await newSpecPage({
      components: [ScFormComponentsValidator],
      template: () => (
        <sc-form-components-validator disabled={false} taxProtocol={{ tax_enabled: true, eu_vat_required: true } as TaxProtocol}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();
    expect(page.root).toMatchSnapshot();
    page.rootInstance.disconnectedCallback();
  });

  it('appends missing trial line item if required', async () => {
    const page = await newSpecPage({
      components: [ScFormComponentsValidator],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-order-summary>
            <sc-line-item-total total="subtotal"></sc-line-item-total>
          </sc-order-summary>
        </sc-form-components-validator>
      ),
    });
    checkoutState.checkout = { trial_amount: 10 } as Checkout;
    await page.waitForChanges();

    expect(page.root).toMatchSnapshot();
    page.rootInstance.disconnectedCallback();
  });

  it('appends missing address field with shipping address required', async () => {
    mockShippingAddressRequired.mockReturnValue(true);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });
    checkoutState.checkout = { shipping_address_required: true } as Checkout;
    await page.waitForChanges();

    expect(page.root).toMatchSnapshot();
    page.rootInstance.disconnectedCallback();
  });

  it('requires the customer name on sc-customer-name if present in page and shipping address required', async () => {
    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerName, ScOrderShippingAddress],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
          <sc-customer-name></sc-customer-name>
          <sc-order-shipping-address></sc-order-shipping-address>
        </sc-form-components-validator>
      ),
    });

    // Wait for components to initialize
    await page.waitForChanges();

    // Set up the checkout state
    checkoutState.checkout = { shipping_address_required: true } as Checkout;
    await page.waitForChanges();

    // Get the instance and trigger the handler
    const instance = page.rootInstance as ScFormComponentsValidator;
    instance.handleShippingAddressRequired();
    await page.waitForChanges();

    const customerName = page.root.querySelector('sc-customer-name');
    expect(customerName.required).toBe(true);

    const shippingAddressElement = page.root.querySelector('sc-order-shipping-address');
    expect(shippingAddressElement.required).toBe(true);
    expect(!!shippingAddressElement.requireName).toBe(false);
    expect(!!shippingAddressElement.showName).toBe(false);

    expect(page.root).toMatchSnapshot();
    page.rootInstance.disconnectedCallback();
  });

  it('requires the customer name on sc-order-shipping-address if shipping address is required', async () => {
    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerName, ScOrderShippingAddress],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
          <sc-order-shipping-address></sc-order-shipping-address>
        </sc-form-components-validator>
      ),
    });

    // Wait for components to initialize
    await page.waitForChanges();

    // Set up the checkout state
    checkoutState.checkout = { shipping_address_required: true } as Checkout;
    await page.waitForChanges();

    // Get the instance and trigger the handler
    const instance = page.rootInstance as ScFormComponentsValidator;
    instance.handleShippingAddressRequired();
    await page.waitForChanges();

    const shippingAddressElement = page.root.querySelector('sc-order-shipping-address');
    expect(shippingAddressElement.required).toBe(true);
    expect(shippingAddressElement.requireName).toBe(true);
    expect(shippingAddressElement.showName).toBe(true);

    expect(page.root).toMatchSnapshot();
    page.rootInstance.disconnectedCallback();
  });

  it('adds a required phone field when the platform requires a shipping phone', async () => {
    mockPhoneRequired.mockReturnValue(true);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerPhone],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();

    const phone = page.root.querySelector('sc-customer-phone');
    expect(phone).not.toBeNull();
    expect(phone.required).toBe(true);

    page.rootInstance.disconnectedCallback();
  });

  it('does not add a phone field for a physical product with flat-rate shipping when the key is absent', async () => {
    // The reporting store: full address accuracy, shipping on, no label provider, no Razorpay.
    checkoutState.checkout = { shipping_enabled: true, shipping_address_accuracy_requirement: 'full' } as Checkout;
    mockShippingAddressRequired.mockReturnValue(true);
    mockFullShippingAddressRequired.mockReturnValue(true);
    mockPhoneRequired.mockReturnValue(false);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerPhone],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();

    expect(page.root.querySelector('sc-customer-phone')).toBeNull();

    page.rootInstance.disconnectedCallback();
  });

  it('does not add a phone field when the platform sets the key to false', async () => {
    checkoutState.checkout = { shipping_enabled: true, shipping_address_accuracy_requirement: 'full', phone_required: false } as Checkout;
    mockShippingAddressRequired.mockReturnValue(true);
    mockFullShippingAddressRequired.mockReturnValue(true);
    mockPhoneRequired.mockReturnValue(false);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerPhone],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();

    expect(page.root.querySelector('sc-customer-phone')).toBeNull();

    page.rootInstance.disconnectedCallback();
  });

  it('adds a required phone field when razorpay is available regardless of the shipping phone key', async () => {
    mockPhoneRequired.mockReturnValue(false);
    mockGetAvailableProcessor.mockReturnValue({ processor_type: 'razorpay' } as unknown as Processor);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerPhone],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();

    const phone = page.root.querySelector('sc-customer-phone');
    expect(phone).not.toBeNull();
    expect(phone.required).toBe(true);

    page.rootInstance.disconnectedCallback();
  });

  it('still adds the billing address on full accuracy without adding a phone', async () => {
    mockShippingAddressRequired.mockReturnValue(true);
    mockFullShippingAddressRequired.mockReturnValue(true);
    mockPhoneRequired.mockReturnValue(false);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerPhone],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();

    expect(page.root.querySelector('sc-order-shipping-address')).not.toBeNull();
    expect(page.root.querySelector('sc-order-billing-address')).not.toBeNull();
    expect(page.root.querySelector('sc-customer-phone')).toBeNull();

    page.rootInstance.disconnectedCallback();
  });

  it('does not add a phone field when only tax accuracy is required', async () => {
    mockShippingAddressRequired.mockReturnValue(true);
    mockFullShippingAddressRequired.mockReturnValue(false);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerPhone],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();

    expect(page.root.querySelector('sc-customer-phone')).toBeNull();

    page.rootInstance.disconnectedCallback();
  });

  it('un-requires the phone it added when the shipping phone is no longer required', async () => {
    mockPhoneRequired.mockReturnValue(true);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerPhone],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();

    const phone = page.root.querySelector('sc-customer-phone');
    expect(phone.required).toBe(true);

    // Removing the label-provider item mid-checkout must not leave the phone stuck required.
    mockPhoneRequired.mockReturnValue(false);
    (page.rootInstance as ScFormComponentsValidator).handlePhoneRequiredForShipping();
    await page.waitForChanges();

    expect(phone.required).toBe(false);

    page.rootInstance.disconnectedCallback();
  });

  it('leaves a merchant-required phone required when the shipping phone is no longer required', async () => {
    mockPhoneRequired.mockReturnValue(true);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerPhone],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
          <sc-customer-phone required></sc-customer-phone>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();

    const phone = page.root.querySelector('sc-customer-phone');
    expect(phone.required).toBe(true);

    mockPhoneRequired.mockReturnValue(false);
    (page.rootInstance as ScFormComponentsValidator).handlePhoneRequiredForShipping();
    await page.waitForChanges();

    // We never claimed this phone, so we must not touch it.
    expect(phone.required).toBe(true);

    page.rootInstance.disconnectedCallback();
  });

  it('escalates an existing optional phone field to required', async () => {
    mockPhoneRequired.mockReturnValue(true);

    const page = await newSpecPage({
      components: [ScFormComponentsValidator, ScCustomerPhone],
      template: () => (
        <sc-form-components-validator disabled={false}>
          <sc-payment></sc-payment>
          <sc-customer-phone></sc-customer-phone>
        </sc-form-components-validator>
      ),
    });
    await page.waitForChanges();

    const phones = page.root.querySelectorAll('sc-customer-phone');
    expect(phones.length).toBe(1);
    expect(phones[0].required).toBe(true);

    page.rootInstance.disconnectedCallback();
  });
});
